options.styles:
.lifecycle-dashboard {
  width: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #eef3f8;
  color: #102a43;
  font-family: "Segoe UI", Arial, sans-serif;
}

.lifecycle-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.lifecycle-title {
  color: #102a43;
  font-size: 23px;
  font-weight: 600;
  line-height: 1.2;
}

.lifecycle-subtitle {
  margin-top: 5px;
  color: #627d98;
  font-size: 13px;
}

.summary-box {
  min-width: 140px;
  padding: 10px 14px;
  border: 1px solid #d4deea;
  border-radius: 7px;
  background: #fff;
  text-align: right;
}

.summary-label {
  display: block;
  color: #627d98;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.summary-value {
  display: block;
  margin-top: 3px;
  font-size: 22px;
  font-weight: 700;
  color: #102a43;
}

.lifecycle-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(180px, 1fr));
  gap: 14px;
}

.lifecycle-card {
  position: relative;
  min-height: 125px;
  padding: 20px 16px 15px;
  border: 1px solid #d4deea;
  border-radius: 7px;
  background: #fff;
  box-shadow: 0 2px 5px rgba(16, 42, 67, .09);
  overflow: hidden;
}

.lifecycle-card:before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 5px;
}

.lifecycle-label {
  min-height: 30px;
  color: #486581;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .5px;
  text-transform: uppercase;
  line-height: 1.3;
}

.lifecycle-value {
  margin-top: 8px;
  color: #102a43;
  font-size: 36px;
  font-weight: 700;
  line-height: 1;
}

.lifecycle-description {
  margin-top: 10px;
  color: #829ab1;
  font-size: 11px;
  line-height: 1.35;
}

.card-blue:before {
  background: #2563eb;
}

.card-cyan:before {
  background: #06b6d4;
}

.card-green:before {
  background: #16a34a;
}

.card-orange:before {
  background: #f97316;
}

.card-red:before {
  background: #dc2626;
}

.card-purple:before {
  background: #9333ea;
}
